// Bundled model catalog lookup — cost/context fallback for models the user has
// not manually priced. Plugs the "unregistered model ⇒ cost silently $0" hole:
// per-call cost now consults MODEL_CATALOG (generated by scripts/gen-models.mjs)
// when the configured ModelOverride carries no price. Pure functions over the
// generated data only: no fs, no network, no registry access.

import {
  MODEL_CATALOG,
  MODEL_CATALOG_SOURCE,
  type ModelCatalogEntry,
} from './model-catalog.generated.js'

export { MODEL_CATALOG_SOURCE }

/** Full bundled catalog shape (provider id → model id → entry). */
export type ModelCatalog = Readonly<
  Record<string, { models: Readonly<Record<string, ModelCatalogEntry>> }>
>

/** Provider reference as available at a cost computation point: the configured
 *  provider name and/or its baseURL. Both are optional — gateways may have
 *  uninformative names, and the registry route may be unavailable. */
export type ProviderRef = {
  /** Configured provider name (registry route id / catalog provider id). */
  readonly providerId?: string
  /** Provider baseURL; its host is matched against known API endpoints. */
  readonly baseURL?: string
}

/** Known first-party API endpoint hosts → bundled catalog provider ids.
 *  Region/resource-parameterized cloud hosts (bedrock/azure/vertex) cannot be
 *  listed exactly and get suffix rules in SUFFIX_HOST_ALIASES below. */
const HOST_ALIASES: Readonly<Record<string, string>> = {
  'api.openai.com': 'openai',
  'api.anthropic.com': 'anthropic',
  'generativelanguage.googleapis.com': 'google',
  'openrouter.ai': 'openrouter',
  'api.deepseek.com': 'deepseek',
  'api.groq.com': 'groq',
  'api.mistral.ai': 'mistral',
  'api.x.ai': 'xai',
  'api.cohere.com': 'cohere',
  'api.fireworks.ai': 'fireworks-ai',
  'api.together.xyz': 'togetherai',
  'dashscope.aliyuncs.com': 'alibaba',
  'dashscope-intl.aliyuncs.com': 'alibaba',
  'api.moonshot.cn': 'moonshotai',
  'api.moonshot.ai': 'moonshotai',
  'api.z.ai': 'zai',
  'open.bigmodel.cn': 'zai',
  'api.siliconflow.com': 'siliconflow',
  'api.siliconflow.cn': 'siliconflow',
  'api.deepinfra.com': 'deepinfra',
  'api.perplexity.ai': 'perplexity',
  'api.novita.ai': 'novita-ai',
  'integrate.api.nvidia.com': 'nvidia',
  'router.huggingface.co': 'huggingface',
  'api.githubcopilot.com': 'github-copilot',
}

/** Host suffix patterns for cloud endpoints whose host embeds region/resource:
 *  bedrock-runtime.<region>.amazonaws.com, <resource>.openai.azure.com,
 *  <region>-aiplatform.googleapis.com. */
const SUFFIX_HOST_ALIASES: ReadonlyArray<readonly [suffix: string, providerId: string]> = [
  ['.amazonaws.com', 'amazon-bedrock'],
  ['.openai.azure.com', 'azure'],
  ['-aiplatform.googleapis.com', 'google-vertex'],
]

/** Trailing date-version suffix on model ids: Anthropic snapshots use
 *  `-YYYYMMDD` (claude-3-5-sonnet-20241022), OpenAI dated deployments use
 *  `-YYYY-MM-DD` (gpt-4o-2024-11-20). */
const DATE_SUFFIX = /-(?:\d{8}|\d{4}-\d{2}-\d{2})$/

/** Model-id candidates in fallback order:
 *  1. the id as given (exact);
 *  2. vendor-prefix-stripped segments (openrouter-style `anthropic/xxx` — also
 *     covers nested `openrouter/anthropic/xxx`);
 *  3. the above with one trailing `-YYYYMMDD` date suffix removed.
 *  Each candidate is tried exactly first, then case-insensitively. */
function candidateIds(modelId: string): string[] {
  const candidates: string[] = [modelId]
  const parts = modelId.split('/')
  for (let i = 1; i < parts.length; i++) {
    candidates.push(parts.slice(i).join('/'))
  }
  for (const base of [...candidates]) {
    const stripped = base.replace(DATE_SUFFIX, '')
    if (stripped !== base) candidates.push(stripped)
  }
  return candidates
}

/** Case-insensitive lookup stays deterministic: catalog keys are sorted, so the
 *  first key whose lowercase form matches wins regardless of upstream ordering. */
function findModelEntry(
  models: Readonly<Record<string, ModelCatalogEntry>>,
  modelId: string,
): ModelCatalogEntry | undefined {
  const candidates = candidateIds(modelId)
  for (const candidate of candidates) {
    const entry = models[candidate]
    if (entry !== undefined) return entry
  }
  const lowered = new Set(candidates.map((candidate) => candidate.toLowerCase()))
  for (const [key, entry] of Object.entries(models)) {
    if (lowered.has(key.toLowerCase())) return entry
  }
  return undefined
}

const normalizeProviderId = (id: string): string => id.trim().toLowerCase()

const hostOf = (baseURL: string): string | null => {
  try {
    return new URL(baseURL).hostname.toLowerCase()
  } catch {
    return null
  }
}

function resolveProviderBucket(
  providerRef: ProviderRef,
  catalog: ModelCatalog,
): { models: Readonly<Record<string, ModelCatalogEntry>> } | null {
  const id = providerRef.providerId
  if (id !== undefined && id.length > 0) {
    const bucket = catalog[normalizeProviderId(id)]
    if (bucket !== undefined) return bucket
  }
  const baseURL = providerRef.baseURL
  if (baseURL !== undefined && baseURL.length > 0) {
    const host = hostOf(baseURL)
    if (host !== null) {
      const aliased = HOST_ALIASES[host]
      if (aliased !== undefined && catalog[aliased] !== undefined) return catalog[aliased]
      for (const [suffix, providerId] of SUFFIX_HOST_ALIASES) {
        if (!host.endsWith(suffix)) continue
        const bucket = catalog[providerId]
        if (bucket !== undefined) return bucket
      }
    }
  }
  return null
}

/** Resolve a (provider, model) pair against the bundled catalog. Returns null
 *  when nothing matches — a missing price must stay unknown, never guessed. */
export function resolveModelCatalogEntry(
  providerRef: ProviderRef,
  modelId: string,
  catalog: ModelCatalog = MODEL_CATALOG,
): ModelCatalogEntry | null {
  if (modelId.length === 0) return null
  const bucket = resolveProviderBucket(providerRef, catalog)
  if (bucket === null) return null
  return findModelEntry(bucket.models, modelId) ?? null
}

/** Per-call cost in USD. Precedence: user-configured $/1k prices always win;
 *  the bundled catalog is consulted only when both configured prices are unset
 *  (0 — the registry's default for unpriced models). Returns null when neither
 *  source knows a price: callers must record an unknown-cost call ($0 + counted
 *  in unknownCostCalls), not a silent $0. A catalog entry with both prices
 *  explicitly 0 is a *known-free* model and yields 0, not null. */
export function costUsdForCall(
  providerRef: ProviderRef,
  modelId: string,
  configured: { readonly costPer1kInput: number; readonly costPer1kOutput: number },
  tokens: { readonly inputTokens: number; readonly outputTokens: number },
  catalog: ModelCatalog = MODEL_CATALOG,
): number | null {
  if (configured.costPer1kInput > 0 || configured.costPer1kOutput > 0) {
    return (
      (tokens.inputTokens / 1000) * configured.costPer1kInput +
      (tokens.outputTokens / 1000) * configured.costPer1kOutput
    )
  }
  const entry = resolveModelCatalogEntry(providerRef, modelId, catalog)
  if (entry === null) return null
  if (entry.inputPricePerMTok === undefined && entry.outputPricePerMTok === undefined) return null
  return (
    (tokens.inputTokens / 1_000_000) * (entry.inputPricePerMTok ?? 0) +
    (tokens.outputTokens / 1_000_000) * (entry.outputPricePerMTok ?? 0)
  )
}
